"use strict";
async function portalRequest(action,body){const response=await fetch('/api/portal/'+action,{credentials:'same-origin',method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw Error(data.error||'The portal is unavailable.');return data;}
(async()=>{try{const session=await portalRequest('session');window.isGameAdmin=session.user?.role==='admin';document.querySelectorAll('[data-profile-link],[data-session-link]').forEach(el=>el.hidden=!session.user);document.querySelectorAll('[data-staff-link]').forEach(el=>el.hidden=session.user?.role!=='admin');document.querySelectorAll('[data-register-link]').forEach(el=>el.hidden=!!session.user);initializePortalControls(session);const label=document.getElementById('portalUser');if(label)label.textContent=session.user?'Signed in as '+session.user.username:'Commander portal';const login=document.getElementById('portalLoginLink');if(login&&session.user){login.textContent='Continue game';login.href='/game';}const form=document.getElementById('loginForm');if(form){if(session.user){location.replace('/game');return;}const setup=session.setupRequired;document.getElementById('loginHeading').textContent=setup?'Create the administrator':'Welcome back';document.getElementById('loginIntro').textContent=setup?'Set up the initial admin account for this game portal.':'Sign in with your game account to enter Starfall Command.';document.getElementById('loginSubmit').textContent=setup?'Create admin account':'Sign in';if(setup){form.elements.username.value='admin';form.elements.username.readOnly=true;}form.addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('loginSubmit'),status=document.getElementById('loginStatus');button.disabled=true;status.textContent='';try{await portalRequest(setup?'setup':'login',{username:form.elements.username.value,password:form.elements.password.value});form.elements.password.value='';location.replace('/game');}catch(error){status.textContent=error.message;button.disabled=false;}});}}catch(error){const status=document.getElementById('loginStatus');if(status)status.textContent=error.message;}})();
const manualSearch=document.getElementById('manualSearch');if(manualSearch)manualSearch.addEventListener('input',()=>{const query=manualSearch.value.trim().toLowerCase();let visible=0;document.querySelectorAll('.manual-section').forEach(section=>{section.hidden=!!query&&!section.textContent.toLowerCase().includes(query);if(!section.hidden)visible++;});document.getElementById('manualSearchStatus').textContent=visible+' categories';});
document.addEventListener('click',async event=>{if(event.target.closest('[data-portal-logout]')){try{await portalRequest('logout',{});location.href='/';}catch(error){alert(error.message);}}});

function applyPortalSkin(skin){if(!['Neutral','Terran','Cathaar','Xandathrii','Zikonian','Eitraides'].includes(skin))skin='Neutral';document.body.dataset.portalSkin=skin;const picker=document.getElementById('portalTheme');if(picker)picker.value=skin;try{localStorage.setItem('starfall-portal-skin',skin);}catch{}}
if(document.getElementById('portalTheme')){let skin='Neutral';try{skin=localStorage.getItem('starfall-portal-skin')||skin;}catch{}applyPortalSkin(skin);}
document.addEventListener('change',event=>{if(event.target.id==='portalTheme')applyPortalSkin(event.target.value);if(event.target.id==='manualShipRace'){const race=event.target.value;document.querySelectorAll('[data-ship-race]').forEach(card=>card.hidden=race!=='all'&&card.dataset.shipRace!==race);}});
document.addEventListener('click',event=>{const button=event.target.closest('[data-preview-race]');if(button)applyPortalSkin(button.dataset.previewRace);});

document.addEventListener('change',event=>{if(event.target.id==='manualStatsRace')document.querySelectorAll('[data-stat-race]').forEach(table=>table.hidden=event.target.value!=='all'&&table.dataset.statRace!==event.target.value);});

async function initializePortalControls(session){const register=document.getElementById('registerForm');if(register){if(session.user){location.replace('/profile.html');return;}register.addEventListener('submit',async e=>{e.preventDefault();const status=document.getElementById('registerStatus');if(register.elements.password.value!==register.elements.confirmPassword.value){status.textContent='Passwords do not match.';return;}const button=register.querySelector('button');button.disabled=true;try{await portalRequest('register',{username:register.elements.username.value,password:register.elements.password.value});register.reset();location.replace('/profile.html');}catch(error){status.textContent=error.message;button.disabled=false;}});}const profile=document.getElementById('profileForm');if(profile){try{const data=await portalRequest('profile');document.getElementById('profileIdentity').textContent='Account: '+data.user.username+' · '+data.user.role;document.getElementById('profilePlanet').textContent=data.planet?'Planet: '+data.planet.name+' · '+data.planet.coords:'No planet assigned. Contact game staff.';profile.elements.displayName.value=data.planet?.username||data.profile.display_name||data.user.username;profile.elements.theme.value=data.profile.theme;profile.addEventListener('submit',async e=>{e.preventDefault();try{await portalRequest('profile',{displayName:profile.elements.displayName.value,theme:profile.elements.theme.value});applyPortalSkin(profile.elements.theme.value);document.getElementById('profileStatus').textContent='Profile saved.';}catch(error){document.getElementById('profileStatus').textContent=error.message;}});}catch(error){document.getElementById('profileStatus').textContent=error.message;}}if(document.getElementById('staffUsers')){try{const data=await portalRequest('staff'),table=document.createElement('table');table.className='table';const head=document.createElement('tr');for(const label of ['Account','Role','Planet','Assign']){const cell=document.createElement('th');cell.textContent=label;head.append(cell);}table.append(head);for(const user of data.users){const row=document.createElement('tr'),name=document.createElement('td'),role=document.createElement('td'),owned=document.createElement('td'),action=document.createElement('td'),select=document.createElement('select'),button=document.createElement('button');name.textContent=user.username;role.textContent=user.role;owned.textContent=data.planets.filter(p=>p.ownerId===user.id).map(p=>p.name+' · '+p.coords).join(', ')||'Unassigned';for(const p of data.planets.filter(p=>!p.ownerId||p.ownerId===user.id)){const option=document.createElement('option');option.value=p.id;option.textContent=p.name+' · '+p.coords;option.selected=p.ownerId===user.id;select.append(option);}button.textContent='ASSIGN PLANET';button.className='button';button.disabled=!select.options.length;button.addEventListener('click',async()=>{try{await portalRequest('staff-assign',{userId:user.id,planetId:select.value});location.reload();}catch(error){document.getElementById('staffStatus').textContent=error.message;}});action.append(select,button);row.append(name,role,owned,action);table.append(row);}document.getElementById('staffUsers').replaceChildren(table);}catch(error){document.getElementById('staffStatus').textContent=error.message;}document.getElementById('staffResetForm').addEventListener('submit',async e=>{e.preventDefault();try{await portalRequest('reset',{confirmation:e.target.elements.confirmation.value});localStorage.removeItem('starfall-round-v2');localStorage.removeItem('starfall-state');document.getElementById('staffResetStatus').textContent='Round reset. Default planets regenerated.';}catch(error){document.getElementById('staffResetStatus').textContent=error.message;}});}}
